widget.solution:
from math import erf, exp, log, sqrt
import numpy as np

def norm_cdf(z):
    return 0.5 * (1 + erf(z / sqrt(2)))

def forward_value(S, K, r, T):
    return S - K * exp(-r * T)

def digital_call(S, K, r, sigma, T):
    d2 = (log(S / K) + (r - sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    return exp(-r * T) * norm_cdf(d2)

def power_price(S, r, sigma, T, n):
    return exp(-r * T) * S ** n * exp(n * (r - sigma ** 2 / 2) * T + n * n * sigma ** 2 * T / 2)

def mc_price(payoff, S, r, sigma, T, paths, seed):
    z = np.random.default_rng(seed).standard_normal(paths)
    S_T = S * np.exp((r - sigma ** 2 / 2) * T + sigma * sqrt(T) * z)
    pv = exp(-r * T) * payoff(S_T)
    return [float(pv.mean()), float(pv.std(ddof=1) / sqrt(paths))]
